import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/troubleshooting.md","filePath":"ja-JP/user-guide/troubleshooting.md","lastUpdated":1785993908000}'),s={name:"ja-JP/user-guide/troubleshooting.md"};function n(i,t,l,h,g,d){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><h2 id="グローバルホットキーが反応しない" tabindex="-1">グローバルホットキーが反応しない <a class="header-anchor" href="#グローバルホットキーが反応しない" aria-label="Permalink to &quot;グローバルホットキーが反応しない&quot;">​</a></h2><ol><li><strong>設定 → サービスの状態</strong> を確認してください — バックグラウンドサービスが実行されていない場合、そのページから再インストールまたは再起動すると、たいていインデックス関連の問題は解消しますが、切り替えホットキー自体はサービスではなく App プロセスが処理しているため、これは二次的な確認事項です。</li><li>フォアグラウンドのアプリが昇格（管理者として実行）されていて Lertaro がそうでない場合、Windows は低い権限のプロセスがそのアプリに入力を送ることをブロックします。Lertaro のバックグラウンドホットキーリスナープロセスは、アカウントが管理者である場合は自動的に昇格されます — 有効にする設定も UAC プロンプトもありません。それでもホットキーが昇格されたウィンドウに届かない場合は、<strong><a href="./settings/service-status.html">設定 → サービスの状態</a></strong> を確認し、バックグラウンドサービスが実行中であることを確かめてください。昇格されたリスナーを起動しているのはこのサービスだからです。アカウントが管理者でない場合、回避策はありません — Windows は低い権限のプロセスが高い権限のプロセスにシグナルを送ることを許可しません。</li><li><strong><a href="./settings/hotkeys-page.html#process-blacklist">プロセスブラックリスト</a></strong> を確認してください — フォアグラウンドアプリの実行ファイル名が（意図的にせよ誤ってにせよ）追加されている場合、そのアプリにフォーカスがある間、Lertaro のグローバルホットキーは意図的に素通しされます。</li><li>フォアグラウンドアプリが本当にフルスクリーン（モニター全体を占有）である場合、Lertaro はデフォルトでそのホットキーも自動的に素通しします — フルスクリーンゲームと競合しないようにするためです。設定したキーの組み合わせがフルスクリーンアプリ自体が使うものと衝突しないのであれば、<strong>設定 → ホットキー → クイック検索の表示/非表示</strong> の横にある <strong>フルスクリーンアプリにフォーカスがあっても応答する</strong> を有効にすれば、そこでも動作するようになります。それ以外の場合は、Alt+Tab で一度切り替えるか、排他的フルスクリーンではなくボーダーレス/ウィンドウモードでアプリを実行することで回避できます。</li></ol><h2 id="検索結果が古いように見える" tabindex="-1">検索結果が古いように見える <a class="header-anchor" href="#検索結果が古いように見える" aria-label="Permalink to &quot;検索結果が古いように見える&quot;">​</a></h2><p>NTFS と ReFS のドライブは USN ジャーナルからほぼリアルタイムで更新されます。それ以外のローカルファイルシステム（FAT32、exFAT など）も同様に継続的に、直接変更が監視されます。それでも古いままに見える場合（作成したばかりのファイルが表示されない、削除したファイルがまだ表示されるなど）は、対象のドライブについて <strong>設定 → インデックス → ローカルドライブ</strong>（または <strong>ネットワークドライブ</strong>）の <strong>インデックスの再構築</strong> を使用してください。</p><h2 id="ネットワークドライブがまったく更新されないように見える" tabindex="-1">ネットワークドライブがまったく更新されないように見える <a class="header-anchor" href="#ネットワークドライブがまったく更新されないように見える" aria-label="Permalink to &quot;ネットワークドライブがまったく更新されないように見える&quot;">​</a></h2><p>ネットワーク共有には Lertaro が監視できる USN ジャーナルがないため、代わりにスケジュールに基づいて再スキャンされます。<strong>設定 → インデックス → ネットワークドライブ</strong> でそのドライブの <strong>更新モード</strong> を確認してください — <strong>手動</strong> に設定されている場合は自動的には更新されません。定期的な間隔に切り替えるか、<strong>インデックスの再構築</strong> でオンデマンドに更新してください。NAS SMB 共有上の特殊なシンボリックリンクや階層ループについては、スキャンエンジンに無限ループ防止機能が組み込まれており、重複ループを回避します。</p><h2 id="プレビューウィンドウの表示がおかしい-一部が切れている" tabindex="-1">プレビューウィンドウの表示がおかしい/一部が切れている <a class="header-anchor" href="#プレビューウィンドウの表示がおかしい-一部が切れている" aria-label="Permalink to &quot;プレビューウィンドウの表示がおかしい/一部が切れている&quot;">​</a></h2><p>通常はこの現象は発生しません — Lertaro は QuickLook プレビューウィンドウの位置とサイズを、モニターの使用可能領域に自動的に収めます。それでもクリッピングが見られる場合は、<strong>設定 → 一般 → プレビュー → プレビューウィンドウ設定をリセット</strong> を試して、通常とは異なる手動の幅/高さの値が原因でないかを確認し、最新版を使用していることも確認してください。</p><h2 id="ファイル-フォルダーがまったく表示されない" tabindex="-1">ファイル/フォルダーがまったく表示されない <a class="header-anchor" href="#ファイル-フォルダーがまったく表示されない" aria-label="Permalink to &quot;ファイル/フォルダーがまったく表示されない&quot;">​</a></h2><ul><li>除外されていないか確認してください — <strong>設定 → インデックス → 除外ルール</strong> は完全一致パス、グロブパターン、正規表現に対応しており、この3つのいずれかが意図せず該当している可能性があります。</li><li>そのファイルがあるドライブが <strong>設定 → インデックス → ローカル/ネットワークドライブ</strong> で有効になっているか確認してください。</li></ul><h2 id="インライン検索ウィンドウで中国語-または他の-ime-言語-を入力できない" tabindex="-1">インライン検索ウィンドウで中国語（または他の IME 言語）を入力できない <a class="header-anchor" href="#インライン検索ウィンドウで中国語-または他の-ime-言語-を入力できない" aria-label="Permalink to &quot;インライン検索ウィンドウで中国語（または他の IME 言語）を入力できない&quot;">​</a></h2><p><a href="./getting-started.html#_3-つのウィンドウ">インラインウィンドウ</a>は、ドッキング先のウィンドウから実際のキーボードフォーカスをあえて奪わないようにしています — これにより、フォーカスのちらつきなしに、インラインウィンドウを閉じて元の場所にぴったり戻ることができます。しかし IME の変換処理（候補リストと、実際に確定される文字）は、実際にフォーカスを持っているウィンドウ、つまり常にドッキング先のアプリでのみ発生し、Lertaro では決して発生しません。そのため、入力内容を取得するために Lertaro が横取りできるメッセージが存在しません。これはインラインウィンドウの仕組み上の構造的な制約であり、バグではありません。</p><p>2つの選択肢があります：</p><ul><li>ピンインのローマ字表記をそのまま入力する（IME の候補ポップアップは不要）— Lertaro は中国語のファイル名をピンインで自動的にマッチさせます。<a href="./search-syntax.html#中国語ファイル名-ピンインエイリアス">検索構文</a>を参照してください。</li><li>代わりに<a href="./getting-started.html#_3-つのウィンドウ">クイックウィンドウ</a>を使用する（デフォルトでは <code>Ctrl</code> のダブルタップ）— これは実際にフォーカスを持つウィンドウなので、そこでは IME の変換が通常どおり機能します。</li></ul><h2 id="それでも解決しない場合" tabindex="-1">それでも解決しない場合 <a class="header-anchor" href="#それでも解決しない場合" aria-label="Permalink to &quot;それでも解決しない場合&quot;">​</a></h2><p>GitHub に Issue を立てる前に、<strong><a href="./settings/service-status.html">設定 → サービスの状態</a></strong> の <strong>Service</strong>、<strong>App</strong>、<strong>Hook</strong> の各ログタブを確認してください — そこの検索ボックスはキーワードで、レベルのドロップダウンは重大度で絞り込みます。</p>',17)])])}const p=a(s,[["render",n]]);export{c as __pageData,p as default};
